contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: deposit amount to put into c for this contract, and amount to collect
    function run(uint depositAmount, uint collectAmount) public payable {
        // ensure this test contract has enough Ether to deposit into c
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record before-values
        uint before_balance_of_test = c.balances(address(this));
        uint before_contract_eth = address(c).balance;

        // Do a deposit into c sending Ether
        c.Deposit{value: depositAmount}();

        // Read balances after deposit
        uint after_balance_of_test = c.balances(address(this));
        uint after_contract_eth = address(c).balance;

        // Ensure deposit behaved sensibly: contract's recorded balance increased by depositAmount
        // (This is a precondition-like sanity check to allow meaningful Collect test below)
        // We don't assert here; instead we require so failing makes the run unreachable for bad inputs
        require(after_balance_of_test >= before_balance_of_test, "balance mapping decreased after deposit");
        require(after_contract_eth >= before_contract_eth, "contract ETH decreased after deposit");

        // Try to Collect collectAmount and observe whether it reverted
        bool didRevert;
        try c.Collect(collectAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read final state
        uint final_balance_of_test = c.balances(address(this));
        uint final_contract_eth = address(c).balance;

        // If Collect did not revert then two things must hold:
        // 1) mapping balance decreased by exactly collectAmount (no extra loss)
        // 2) contract's ETH decreased by at least collectAmount (funds forwarded out)
        // Otherwise (if reverted) no requirement about state change is enforced here.
        assert(didRevert || (final_balance_of_test + collectAmount == after_balance_of_test && after_contract_eth >= final_contract_eth + collectAmount));
    }

    // Allow this contract to receive refunds from c during Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to deposit into c, collectAmount to attempt to collect
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // step1: ensure this contract has at least depositAmount in c by depositing
        // call Deposit with value depositAmount
        c.Deposit{value: depositAmount}();

        // read balance before collect
        uint before = c.balances(address(this));
        // Ensure before reflects the deposit (sanity): must be >= depositAmount
        // (we don't assert here; just proceed)

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint after = c.balances(address(this));

        // Observed change in this contract's ETH balance (external to c)
        uint thisBal = address(this).balance;

        // The invariant: if Collect did not revert then
        // 1) c.balances decreased by exactly collectAmount (before - after == collectAmount)
        // 2) this contract's ether balance increased by exactly collectAmount
        // If Collect reverted then balances did not change (after == before) and this contract balance unchanged
        // We express this as a single assert over observed values.
        assert(
            (!reverted && before >= collectAmount && before - after == collectAmount && thisBal >= collectAmount) ||
            (reverted && after == before)
        );
    }

    // allow receiving ETH when c sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to deposit into c first, collectAmount to attempt to collect
    function run(uint depositAmount, uint collectAmount) public payable {
        // we will send depositAmount to c, so ensure this contract has it
        require(address(this).balance >= depositAmount);

        // Make a deposit so this contract has an on-contract balance to collect from
        c.Deposit{value: depositAmount}();

        // read balance before collect
        uint balBefore = c.balances(address(this));

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint balAfter = c.balances(address(this));

        // external balance observed (this contract). If collect succeeded, this contract should have
        // received the funds (increase by at least collectAmount). If reverted, external balance unchanged
        uint extBal = address(this).balance;

        // Single assert expressing the general rule:
        // - If Collect did not revert then balBefore >= collectAmount, balBefore - balAfter == collectAmount,
        //   and extBal increased by at least collectAmount relative to having deposited (we know extBal <= initial - deposit + collectAmount,
        //   but we cannot read initial here; instead we require extBal >= 0 and express that collect implies balances change in c exactly.)
        // To avoid referencing the initial external balance, we assert that if Collect succeeded then balBefore >= collectAmount
        // and balBefore - balAfter == collectAmount and extBal >= 0 (trivially true), combined into the meaningful parts.

        assert(
            (!reverted && balBefore >= collectAmount && balBefore - balAfter == collectAmount) ||
            (reverted && balAfter == balBefore)
        );
    }

    // allow receiving ETH when c sends funds
    receive() external payable {}
}

